svg.script:
(function() {
// ── Pan/Zoom ──────────────────────────────────────────────────────────────
const svg = document.getElementById('vis-svg');
const vis = document.getElementById('vis');
const VW = 1258.0, VH = 360.0;
let tx = 0, ty = 0, sc = 1;

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function clampT() {
  tx = clamp(tx, VW * (1 - sc), 0);
  ty = clamp(ty, VH * (1 - sc), 0);
}
function applyT() {
  vis.setAttribute('transform', `translate(${tx},${ty}) scale(${sc})`);
}

svg.addEventListener('wheel', e => {
  e.preventDefault();
  const r = svg.getBoundingClientRect();
  const vx = (e.clientX - r.left) / r.width  * VW;
  const vy = (e.clientY - r.top)  / r.height * VH;
  const f  = e.deltaY < 0 ? 1.12 : 1/1.12;
  const newSc = Math.max(1, sc * f);
  tx = vx - (vx - tx) * (newSc / sc);
  ty = vy - (vy - ty) * (newSc / sc);
  sc = newSc; clampT(); applyT();
}, {passive: false});

let drag = false, dx0, dy0;
svg.addEventListener('mousedown', e => {
  if (e.button !== 0) return;
  drag = true; dx0 = e.clientX - tx; dy0 = e.clientY - ty;
  svg.style.cursor = 'grabbing';
});
window.addEventListener('mousemove', e => {
  if (!drag) return;
  tx = e.clientX - dx0; ty = e.clientY - dy0; clampT(); applyT();
});
window.addEventListener('mouseup', () => { drag = false; svg.style.cursor = 'grab'; });
})();
